begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,auth,pg_catalog;
select no_plan();
\ir helpers/reminder_521_fixtures.sql
update private.learner_profile_access_control set rollout_state='signed-in-public' where singleton;
select ok(not public.reminder_delivery_is_enabled(),'migration leaves independent delivery switch off');
select ok(has_function_privilege('service_role','public.claim_due_typed_reminder_live(timestamptz,integer,integer,integer)','execute'),'trusted worker has typed claim capability');
select ok(not has_function_privilege('authenticated','public.claim_due_typed_reminder_live(timestamptz,integer,integer,integer)','execute'),'browser cannot claim');
select throws_ok($$select * from public.claim_due_typed_reminder_live('2026-10-26T11:05:00Z')$$,'P0001','reminder_delivery_disabled','off switch blocks live work');
select pg_temp.email_fixture('52120000-0000-4000-8000-000000000001','Asia/Taipei','2026-10-26',9,10);
select public.refresh_reminder_eligibility_snapshots(10,'2026-10-26T11:00:00Z');
update private.reminder_delivery_control set delivery_enabled=true;
select is((select count(*) from public.claim_due_typed_reminder_live('2026-10-26T11:05:00Z')),0::bigint,'unknown provider capacity prevents claim');
select pg_temp.email_capacity('2026-10-26T11:05:00Z');
create temporary table claimed_email as select * from public.claim_due_typed_reminder_live('2026-10-26T11:05:00Z');
select is((select count(*) from claimed_email),1::bigint,'live claim automatically plans without dry-run preparation');
select is((select email_type from claimed_email),'streak','streak wins over discovery when both choices enabled');
select is((select count(*) from public.claim_due_typed_reminder_live('2026-10-26T11:05:00Z')),0::bigint,'overlapping tick cannot claim an active lease');
select ok(not public.begin_typed_reminder_provider_attempt((select claim_token from claimed_email),'resend','2026-10-26T11:05:00Z'),'provider begin requires frozen payload binding');
select ok(public.store_typed_reminder_unsubscribe_token((select delivery_id from claimed_email),(select claim_token from claimed_email),decode(repeat('ab',32),'hex'),'2026-10-26T11:05:00Z'),'bind opaque unsubscribe capability');
select ok(pg_temp.bind_email((select claim_token from claimed_email),'2026-10-26T11:05:00Z'),'bind exact first payload');
select ok(not pg_temp.bind_email((select claim_token from claimed_email),'2026-10-26T11:05:00Z','changed-payload'),'retry cannot bind a different payload under stable key');
select ok(public.begin_typed_reminder_provider_attempt((select claim_token from claimed_email),'resend','2026-10-26T11:05:00Z'),'final owner/progress/enrollment/recipient fence consumes capacity');
select is((select count(*) from private.reminder_quota_reservations where consumed_at is not null),1::bigint,'network boundary consumes one atomic quota reservation');
select ok(not public.release_unstarted_reminder_capacity((select delivery_id from claimed_email),'2026-10-26T11:06:00Z'),'started or uncertain attempt can never release reservation');
insert into private.reminder_quota_reservations(delivery_id,utc_date,reserved_at,consumed_at)
select extensions.gen_random_uuid(),'2026-10-26','2026-10-26T11:05:00Z','2026-10-26T11:05:00Z' from generate_series(1,59);
select ok(public.defer_typed_reminder((select claim_token from claimed_email),60,false,false,'2026-10-26T11:05:10Z'),'network ambiguity records durable next attempt');
select is((select count(*) from public.claim_due_typed_reminder_live('2026-10-26T11:05:30Z')),0::bigint,'retry does not ignore next_attempt_at');
create temporary table retried_email as select * from public.claim_due_typed_reminder_live('2026-10-26T11:06:10Z');
select is((select delivery_id from retried_email),(select delivery_id from claimed_email),'retry keeps stable delivery UUID');
select ok(pg_temp.bind_email((select claim_token from retried_email),'2026-10-26T11:06:10Z'),'identical payload can bind again');
select ok(public.begin_typed_reminder_provider_attempt((select claim_token from retried_email),'resend','2026-10-26T11:06:10Z'),'same-period retry reuses reservation');
select is((select count(*) from private.reminder_quota_reservations),60::bigint,'fullbudget retry reuses its slot without consuming another quota slot');
select ok(public.complete_reminder_provider_acceptance((select claim_token from retried_email),'resend','provider-message-521','2026-10-26T11:06:11Z'),'API acceptance is recorded separately from delivery');
select is((select count(*) from public.claim_due_typed_reminder_live('2026-10-26T11:10:00Z')),0::bigint,'accepted occurrence cannot be reclaimed');
select is((select count(*) from private.reminder_provider_events),0::bigint,'API accepted does not invent inbox delivery');
select is((select count(*) from public.claim_due_typed_reminder_live('2026-10-26T12:00:00Z')),0::bigint,'one-hour cutoff never sends late');
select * from finish();
rollback;
